PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS "AdminUser" ("id" TEXT NOT NULL PRIMARY KEY, "email" TEXT NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "Store" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT 0, "integrationStatus" TEXT NOT NULL DEFAULT 'disabled', "note" TEXT);
CREATE TABLE IF NOT EXISTS "Niche" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL UNIQUE, "wantedKeywords" TEXT NOT NULL, "forbiddenKeywords" TEXT NOT NULL DEFAULT '[]', "allowedBrands" TEXT NOT NULL DEFAULT '[]', "forbiddenBrands" TEXT NOT NULL DEFAULT '[]', "minPrice" REAL NOT NULL DEFAULT 0, "maxPrice" REAL NOT NULL DEFAULT 100000, "minDiscount" REAL NOT NULL DEFAULT 10, "minRating" REAL NOT NULL DEFAULT 0, "minReviewCount" INTEGER NOT NULL DEFAULT 0, "minSellerReputation" REAL NOT NULL DEFAULT 0, "freeShippingRequired" BOOLEAN NOT NULL DEFAULT 0, "enabledStores" TEXT NOT NULL DEFAULT '[]', "maxOffers" INTEGER NOT NULL DEFAULT 10, "searchTimes" TEXT NOT NULL DEFAULT '["09:00","18:00"]', "publishIntervalMinutes" INTEGER NOT NULL DEFAULT 15, "active" BOOLEAN NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS "Offer" ("id" TEXT NOT NULL PRIMARY KEY, "externalId" TEXT NOT NULL, "storeId" TEXT NOT NULL REFERENCES "Store"("id"), "nicheId" TEXT REFERENCES "Niche"("id"), "title" TEXT NOT NULL, "imageUrl" TEXT, "originalUrl" TEXT NOT NULL, "affiliateUrl" TEXT, "currentPrice" REAL NOT NULL, "previousPrice" REAL, "discountPercent" REAL, "rating" REAL, "reviewCount" INTEGER, "commissionPercent" REAL, "extraCommissionPercent" REAL, "estimatedCommission" REAL, "seller" TEXT, "sellerReputation" REAL, "shipping" TEXT, "freeShipping" BOOLEAN NOT NULL DEFAULT 0, "stock" INTEGER, "soldQuantity" INTEGER, "sellerLevel" TEXT, "fullShipping" BOOLEAN NOT NULL DEFAULT 0, "reviewSentiment" REAL, "reviewsAnalyzed" INTEGER NOT NULL DEFAULT 0, "reviewSignals" TEXT NOT NULL DEFAULT '[]', "promotionEndsAt" DATETIME, "score" REAL NOT NULL DEFAULT 0, "status" TEXT NOT NULL DEFAULT 'pending', "discoveredAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "publishedAt" DATETIME, "rawData" TEXT NOT NULL DEFAULT '{}', UNIQUE("storeId","externalId"));
CREATE INDEX IF NOT EXISTS "Offer_status_score_idx" ON "Offer"("status","score");
CREATE TABLE IF NOT EXISTS "PriceHistory" ("id" TEXT NOT NULL PRIMARY KEY, "offerId" TEXT NOT NULL REFERENCES "Offer"("id") ON DELETE CASCADE, "price" REAL NOT NULL, "collectedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "SalesHistory" ("id" TEXT NOT NULL PRIMARY KEY, "offerId" TEXT NOT NULL REFERENCES "Offer"("id") ON DELETE CASCADE, "soldQuantity" INTEGER NOT NULL, "collectedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "SalesHistory_offerId_collectedAt_idx" ON "SalesHistory"("offerId", "collectedAt");
CREATE TABLE IF NOT EXISTS "AffiliateLink" ("id" TEXT NOT NULL PRIMARY KEY, "offerId" TEXT NOT NULL REFERENCES "Offer"("id") ON DELETE CASCADE, "url" TEXT NOT NULL, "source" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "Publication" ("id" TEXT NOT NULL PRIMARY KEY, "offerId" TEXT NOT NULL REFERENCES "Offer"("id") ON DELETE CASCADE, "destination" TEXT NOT NULL DEFAULT 'manual', "message" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'queued', "attempts" INTEGER NOT NULL DEFAULT 0, "nextAttemptAt" DATETIME, "lastError" TEXT, "scheduledAt" DATETIME, "publishedAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "SchedulerRun" ("id" TEXT NOT NULL PRIMARY KEY, "trigger" TEXT NOT NULL, "status" TEXT NOT NULL, "startedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "finishedAt" DATETIME, "foundCount" INTEGER NOT NULL DEFAULT 0, "errorCount" INTEGER NOT NULL DEFAULT 0, "details" TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS "Setting" ("key" TEXT NOT NULL PRIMARY KEY, "value" TEXT NOT NULL, "updatedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "AuditLog" ("id" TEXT NOT NULL PRIMARY KEY, "action" TEXT NOT NULL, "entityType" TEXT NOT NULL, "entityId" TEXT, "metadata" TEXT NOT NULL DEFAULT '{}', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "ApiIdempotencyKey" ("id" TEXT NOT NULL PRIMARY KEY, "key" TEXT NOT NULL, "operation" TEXT NOT NULL, "requestHash" TEXT NOT NULL, "responseStatus" INTEGER, "responseBody" TEXT, "state" TEXT NOT NULL DEFAULT 'processing', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "expiresAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "ApiIdempotencyKey_operation_key_key" ON "ApiIdempotencyKey"("operation", "key");
CREATE INDEX IF NOT EXISTS "ApiIdempotencyKey_expiresAt_idx" ON "ApiIdempotencyKey"("expiresAt");
CREATE TABLE IF NOT EXISTS "WhatsAppAgent" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "companyName" TEXT NOT NULL DEFAULT '', "niche" TEXT NOT NULL DEFAULT '', "role" TEXT NOT NULL DEFAULT 'Atendimento', "persona" TEXT NOT NULL DEFAULT '', "mission" TEXT NOT NULL DEFAULT '', "audience" TEXT NOT NULL DEFAULT '', "tone" TEXT NOT NULL DEFAULT '[]', "objectives" TEXT NOT NULL DEFAULT '[]', "qualifyingQuestions" TEXT NOT NULL DEFAULT '[]', "knowledgeBase" TEXT NOT NULL DEFAULT '', "tools" TEXT NOT NULL DEFAULT '[]', "restrictions" TEXT NOT NULL DEFAULT '', "humanHandoff" TEXT NOT NULL DEFAULT '', "status" TEXT NOT NULL DEFAULT 'draft', "generatedPrompt" TEXT NOT NULL DEFAULT '', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
